Index: /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/UITests/ActionTests.swift
===================================================================
--- /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/UITests/ActionTests.swift
+++ /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/UITests/ActionTests.swift
@@ -3,9 +3,14 @@
   func testReact() {
     let app = XCUIApplication(bundleIdentifier: "im.vector.app")
     app.activate()
     let window = app.windows.firstMatch
+    window.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(dx: 15, dy: 75)).tap()
+    sleep(2)
     window.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(dx: 200, dy: 575)).press(forDuration: 1.2)
     sleep(2)
-    window.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(dx: 33, dy: 500)).tap()
+    try? app.debugDescription.write(toFile: "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/reactmenu.txt", atomically: true, encoding: .utf8)
+    let tree = app.debugDescription
+    if tree.contains("Thumbs up") { app.buttons["Thumbs up"].tap() }
+    else { window.coordinate(withNormalizedOffset: .zero).withOffset(CGVector(dx: 33, dy: 500)).tap() }
   }
 }
